using System;
using System.Collections.Generic;
using Framework.AI.Perception;
using Game.AI.Core;
using UnityEngine;

namespace Game.AI.Perception
{
    /// <summary>
    /// 敵AIによる対象の視認と記憶を管理する。
    /// </summary>
    /// <remarks>
    /// 対象の現在情報は外部から供給する。
    /// 認識判定に成功した情報のみを観測情報へ反映する。
    /// コンテキストの認識記憶は本クラスが管理する。
    /// Unityのメインスレッドで使用することを想定する。
    /// </remarks>
    public sealed class MazeEnemyPerceptionController
        : IDisposable
    {
        /// <summary>
        /// 認識処理に使用する敵AIコンテキスト。
        /// </summary>
        private readonly MazeEnemyContext context;

        /// <summary>
        /// 現在保持している対象の観測情報。
        /// </summary>
        private readonly Dictionary<
            Guid,
            MazeEnemyTargetObservation> observations =
            new Dictionary<Guid, MazeEnemyTargetObservation>();

        /// <summary>
        /// 今回の更新で処理した対象識別子。
        /// </summary>
        private readonly HashSet<Guid> processedIds =
            new HashSet<Guid>();

        /// <summary>
        /// 今回の更新で視認できた対象識別子。
        /// </summary>
        private readonly HashSet<Guid> visibleIds =
            new HashSet<Guid>();

        /// <summary>
        /// 観測情報の安全な列挙に使用する識別子一覧。
        /// </summary>
        private readonly List<Guid> observationIds =
            new List<Guid>();

        /// <summary>
        /// 認識更新やイベント通知を実行しているか。
        /// </summary>
        private bool isProcessing;

        /// <summary>
        /// 破棄済みであるか。
        /// </summary>
        private bool isDisposed;

        /// <summary>
        /// 認識処理に使用するコンテキスト。
        /// </summary>
        public MazeEnemyContext Context => context;

        /// <summary>
        /// 現在保持している観測情報の件数。
        /// </summary>
        public int Count => observations.Count;

        /// <summary>
        /// 視認中の対象数。
        /// </summary>
        public int VisibleCount { get; private set; }

        /// <summary>
        /// 記憶中の対象数。
        /// </summary>
        public int RememberedCount =>
            Count - VisibleCount;

        /// <summary>
        /// 認識制御システムが利用可能であるか。
        /// </summary>
        public bool IsValid =>
            !isDisposed && context.IsValid;

        /// <summary>
        /// 破棄済みであるか。
        /// </summary>
        public bool IsDisposed => isDisposed;

        /// <summary>
        /// 対象を発見または再発見した際のイベント。
        /// </summary>
        public event Action<MazeEnemyTargetObservation>
            TargetDetected;

        /// <summary>
        /// 視認対象を見失った際のイベント。
        /// </summary>
        public event Action<MazeEnemyTargetObservation>
            TargetLost;

        /// <summary>
        /// 対象の記憶を失った際のイベント。
        /// </summary>
        public event Action<Guid> TargetForgotten;

        /// <summary>
        /// 対象の認識状態が変化した際のイベント。
        /// </summary>
        public event Action<
            Guid,
            MazeEnemyTargetState,
            MazeEnemyTargetState> TargetStateChanged;

        /// <summary>
        /// 認識制御システムを生成する。
        /// </summary>
        /// <param name="context">敵AIコンテキスト</param>
        /// <exception cref="ArgumentNullException">
        /// コンテキストが指定されていない場合。
        /// </exception>
        /// <exception cref="ArgumentException">
        /// コンテキストが無効な場合。
        /// </exception>
        public MazeEnemyPerceptionController(
            MazeEnemyContext context)
        {
            if (context == null)
            {
                throw new ArgumentNullException(
                    nameof(context));
            }

            if (!context.IsValid)
            {
                throw new ArgumentException(
                    "敵AIコンテキストが無効です。",
                    nameof(context));
            }

            this.context = context;
        }

        /// <summary>
        /// 認識対象の一覧を使用して認識情報を更新する。
        /// </summary>
        /// <param name="targets">
        /// 今回の認識判定対象となる全対象の一覧
        /// </param>
        /// <returns>
        /// 更新を実行できた場合はtrue
        /// </returns>
        /// <remarks>
        /// 一覧に含まれない対象は視認できないものとして扱う。
        /// 同一識別子が複数ある場合は最初の有効な情報を使用する。
        /// ステージの停止中は更新しない。
        /// </remarks>
        public bool UpdatePerception(
            IReadOnlyList<MazeEnemyTargetSnapshot> targets)
        {
            if (!CanModify() ||
                !context.CanAct ||
                targets == null)
            {
                return false;
            }

            isProcessing = true;

            try
            {
                processedIds.Clear();
                visibleIds.Clear();

                // 現在視認できる対象を更新する。
                for (int i = 0; i < targets.Count; i++)
                {
                    MazeEnemyTargetSnapshot target =
                        targets[i];

                    if (!target.IsValid ||
                        !processedIds.Add(target.Id))
                    {
                        continue;
                    }

                    if (!target.IsActive ||
                        target.Id == context.Id)
                    {
                        continue;
                    }

                    // 同じ識別子の対象種類は変更しない。
                    if (observations.TryGetValue(
                        target.Id,
                        out var previous) &&
                        previous.Type != target.Type)
                    {
                        continue;
                    }

                    if (TryObserve(
                        target,
                        out var stimulus))
                    {
                        visibleIds.Add(target.Id);

                        ApplyVisibleObservation(
                            target,
                            stimulus);
                    }
                }

                // 視認できなかった既存対象を処理する。
                CopyObservationIds();

                for (int i = 0;
                    i < observationIds.Count;
                    i++)
                {
                    Guid id = observationIds[i];

                    if (visibleIds.Contains(id))
                    {
                        continue;
                    }

                    UpdateHiddenObservation(id);
                }

                // 不要な認識記憶を整理する。
                context.RemoveExpiredObservations();

                return true;
            }
            finally
            {
                processedIds.Clear();
                visibleIds.Clear();
                observationIds.Clear();

                isProcessing = false;
            }
        }

        /// <summary>
        /// 指定対象の観測情報を取得する。
        /// </summary>
        /// <param name="id">対象識別子</param>
        /// <param name="observation">取得した観測情報</param>
        /// <returns>観測情報が存在する場合はtrue</returns>
        public bool TryGetObservation(
            Guid id,
            out MazeEnemyTargetObservation observation)
        {
            observation = default;

            return IsValid &&
                observations.TryGetValue(
                    id,
                    out observation);
        }

        /// <summary>
        /// 指定対象の認識状態を取得する。
        /// </summary>
        /// <param name="id">対象識別子</param>
        /// <returns>対象の認識状態</returns>
        public MazeEnemyTargetState GetState(Guid id)
        {
            return TryGetObservation(
                id,
                out var observation)
                    ? observation.State
                    : MazeEnemyTargetState.Unknown;
        }

        /// <summary>
        /// 指定種類の優先認識対象を取得する。
        /// </summary>
        /// <param name="type">対象の種類</param>
        /// <param name="observation">優先対象の観測情報</param>
        /// <returns>対象を取得できた場合はtrue</returns>
        /// <remarks>
        /// 視認中、信頼度、観測位置までの直線距離の順に
        /// 優先順位を決定する。
        /// </remarks>
        public bool TryGetBestObservation(
            MazeEnemyTargetType type,
            out MazeEnemyTargetObservation observation)
        {
            observation = default;

            if (!IsValid)
            {
                return false;
            }

            bool found = false;

            foreach (var pair in observations)
            {
                MazeEnemyTargetObservation candidate =
                    pair.Value;

                if (candidate.Type != type)
                {
                    continue;
                }

                if (!found ||
                    IsBetterObservation(
                        candidate,
                        observation))
                {
                    observation = candidate;
                    found = true;
                }
            }

            return found;
        }

        /// <summary>
        /// 現在保持している観測情報一覧を取得する。
        /// </summary>
        /// <param name="results">観測情報の格納先</param>
        /// <returns>取得した観測情報の件数</returns>
        /// <exception cref="ArgumentNullException">
        /// 格納先が指定されていない場合。
        /// </exception>
        public int GetObservations(
            List<MazeEnemyTargetObservation> results)
        {
            if (results == null)
            {
                throw new ArgumentNullException(
                    nameof(results));
            }

            results.Clear();

            if (!IsValid)
            {
                return 0;
            }

            foreach (var pair in observations)
            {
                results.Add(pair.Value);
            }

            return results.Count;
        }

        /// <summary>
        /// 指定対象の認識情報を明示的に削除する。
        /// </summary>
        /// <param name="id">対象識別子</param>
        /// <returns>削除できた場合はtrue</returns>
        public bool Forget(Guid id)
        {
            if (!CanModify())
            {
                return false;
            }

            isProcessing = true;

            try
            {
                return RemoveObservation(id);
            }
            finally
            {
                isProcessing = false;
            }
        }

        /// <summary>
        /// すべての対象の認識情報を削除する。
        /// </summary>
        /// <returns>削除処理を実行できた場合はtrue</returns>
        public bool Clear()
        {
            if (!CanModify())
            {
                return false;
            }

            isProcessing = true;

            try
            {
                CopyObservationIds();

                for (int i = 0;
                    i < observationIds.Count;
                    i++)
                {
                    RemoveObservation(
                        observationIds[i]);
                }

                return true;
            }
            finally
            {
                observationIds.Clear();
                isProcessing = false;
            }
        }

        /// <summary>
        /// 対象の視認判定を行う。
        /// </summary>
        /// <param name="target">認識対象の現在情報</param>
        /// <param name="stimulus">取得した視覚刺激</param>
        /// <returns>視認できた場合はtrue</returns>
        private bool TryObserve(
            MazeEnemyTargetSnapshot target,
            out PerceptionStimulus<Vector2Int> stimulus)
        {
            stimulus = default;

            if (!context.IsWalkable(target.Position))
            {
                return false;
            }

            var sensor =
                target.Type == MazeEnemyTargetType.Threat
                    ? context.ThreatVisionSensor
                    : context.VisionSensor;

            return sensor.TryObserve(
                target.Id,
                context.CurrentCell,
                context.CurrentDirection,
                target.Position,
                context.CurrentTime,
                out stimulus);
        }

        /// <summary>
        /// 視認できた対象の観測情報を更新する。
        /// </summary>
        /// <param name="target">対象の現在情報</param>
        /// <param name="stimulus">視覚刺激</param>
        private void ApplyVisibleObservation(
            MazeEnemyTargetSnapshot target,
            PerceptionStimulus<Vector2Int> stimulus)
        {
            bool existed = observations.TryGetValue(
                target.Id,
                out var previous);

            MazeEnemyTargetState previousState =
                existed
                    ? previous.State
                    : MazeEnemyTargetState.Unknown;

            // 記憶機能が無効でも現在の視認情報は保持する。
            context.RememberObservation(stimulus);

            var observation =
                new MazeEnemyTargetObservation(
                    target.Id,
                    target.Type,
                    MazeEnemyTargetState.Visible,
                    stimulus.Position,
                    target.Direction,
                    target.MoveSpeed,
                    stimulus.Timestamp,
                    stimulus.Confidence);

            observations[target.Id] = observation;

            if (previousState !=
                MazeEnemyTargetState.Visible)
            {
                VisibleCount++;

                TargetDetected?.Invoke(observation);

                TargetStateChanged?.Invoke(
                    target.Id,
                    previousState,
                    MazeEnemyTargetState.Visible);
            }
        }

        /// <summary>
        /// 視認できなかった対象の記憶状態を更新する。
        /// </summary>
        /// <param name="id">対象識別子</param>
        private void UpdateHiddenObservation(Guid id)
        {
            if (!observations.TryGetValue(
                id,
                out var previous))
            {
                return;
            }

            bool wasVisible = previous.IsVisible;

            bool hasMemory =
                context.TryRecallObservation(
                    id,
                    out var stimulus,
                    out float confidence);

            if (!hasMemory || confidence <= 0f)
            {
                // 見失った状態を通知した後、記憶を削除する。
                RemoveObservation(
                    id,
                    notifyLost: wasVisible);

                return;
            }

            // 現在の対象情報は使用せず、
            // 最後に視認した情報のみを保持する。
            var remembered =
                new MazeEnemyTargetObservation(
                    id,
                    previous.Type,
                    MazeEnemyTargetState.Remembered,
                    stimulus.Position,
                    previous.LastKnownDirection,
                    previous.LastKnownMoveSpeed,
                    stimulus.Timestamp,
                    confidence);

            observations[id] = remembered;

            if (wasVisible)
            {
                VisibleCount--;

                TargetLost?.Invoke(remembered);

                TargetStateChanged?.Invoke(
                    id,
                    MazeEnemyTargetState.Visible,
                    MazeEnemyTargetState.Remembered);
            }
        }

        /// <summary>
        /// 観測情報と対応する認識記憶を削除する。
        /// </summary>
        /// <param name="id">対象識別子</param>
        /// <param name="notifyLost">
        /// 視認喪失イベントも通知するか
        /// </param>
        /// <returns>削除できた場合はtrue</returns>
        private bool RemoveObservation(
            Guid id,
            bool notifyLost = false)
        {
            if (!observations.TryGetValue(
                id,
                out var previous))
            {
                return false;
            }

            observations.Remove(id);

            context.PerceptionMemory.Forget(id);

            if (previous.IsVisible)
            {
                VisibleCount--;
            }

            if (notifyLost)
            {
                var lost =
                    new MazeEnemyTargetObservation(
                        id,
                        previous.Type,
                        MazeEnemyTargetState.Unknown,
                        previous.LastKnownPosition,
                        previous.LastKnownDirection,
                        previous.LastKnownMoveSpeed,
                        previous.LastSeenTime,
                        0f);

                TargetLost?.Invoke(lost);
            }

            TargetForgotten?.Invoke(id);

            TargetStateChanged?.Invoke(
                id,
                previous.State,
                MazeEnemyTargetState.Unknown);

            return true;
        }

        /// <summary>
        /// 候補が現在の優先対象より適切か確認する。
        /// </summary>
        /// <param name="candidate">比較対象</param>
        /// <param name="currentBest">現在の優先対象</param>
        /// <returns>比較対象を優先する場合はtrue</returns>
        private bool IsBetterObservation(
            MazeEnemyTargetObservation candidate,
            MazeEnemyTargetObservation currentBest)
        {
            if (candidate.IsVisible !=
                currentBest.IsVisible)
            {
                return candidate.IsVisible;
            }

            if (candidate.Confidence !=
                currentBest.Confidence)
            {
                return candidate.Confidence >
                    currentBest.Confidence;
            }

            Vector2 candidateOffset =
                candidate.LastKnownPosition -
                context.CurrentCell;

            Vector2 currentOffset =
                currentBest.LastKnownPosition -
                context.CurrentCell;

            float candidateDistance =
                candidateOffset.sqrMagnitude;

            float currentDistance =
                currentOffset.sqrMagnitude;

            if (candidateDistance != currentDistance)
            {
                return candidateDistance <
                    currentDistance;
            }

            // 完全な同点時は識別子で安定した順序を決定する。
            return candidate.Id.CompareTo(
                currentBest.Id) < 0;
        }

        /// <summary>
        /// 現在保持している対象識別子を作業一覧へ複製する。
        /// </summary>
        private void CopyObservationIds()
        {
            observationIds.Clear();

            foreach (var pair in observations)
            {
                observationIds.Add(pair.Key);
            }
        }

        /// <summary>
        /// 認識情報を変更できる状態か確認する。
        /// </summary>
        /// <returns>変更可能な場合はtrue</returns>
        private bool CanModify()
        {
            return IsValid && !isProcessing;
        }

        /// <summary>
        /// 認識制御システムを破棄する。
        /// </summary>
        /// <remarks>
        /// 本クラスが管理している対象の記憶のみを削除する。
        /// コンテキストやパラメーターは破棄しない。
        /// 破棄時に認識イベントは通知しない。
        /// </remarks>
        /// <exception cref="InvalidOperationException">
        /// 認識処理やイベント通知の実行中に呼び出された場合。
        /// </exception>
        public void Dispose()
        {
            if (isDisposed)
            {
                return;
            }

            if (isProcessing)
            {
                throw new InvalidOperationException(
                    "認識処理中は破棄できません。");
            }

            isDisposed = true;

            if (!context.IsDisposed)
            {
                foreach (var pair in observations)
                {
                    context.PerceptionMemory.Forget(
                        pair.Key);
                }
            }

            observations.Clear();
            observationIds.Clear();
            processedIds.Clear();
            visibleIds.Clear();

            VisibleCount = 0;

            TargetDetected = null;
            TargetLost = null;
            TargetForgotten = null;
            TargetStateChanged = null;
        }
    }
}
